style.css:
@-moz-document domain("roblox.com") {
.ad,.ad *,.img_ad,.ad-annotations,#google_image_div,#aw0,#AdvertisingLeaderboard
  {
    display: none !important;
  }

  .ad,.ad *,.img_ad,.ad-annotations,#google_image_div,#aw0,#AdvertisingLeaderboard
  {
    display: none !important;
  }
/*Style by @Keixsra/sarohaplays*/
  #header
  {
    background-color: #faeac6;
  }

  .navigation .notification-icon, .rbx-highlight
  {
    background: #faeac6;
  }

  #chat-header
  {
    background: #fbf7c7;
  }

  .slide-item-container-left,.profile-avatar-right
  {
    background: #faeac6;
  }

  .rbx-tabs-horizontal .rbx-tab.active .rbx-tab-heading, .rbx-tabs-horizontal .rbx-tab-heading:hover, .rbx-tabs-horizontal .rbx-tab-heading:focus, .rbx-tabs-horizontal .rbx-tab-heading:active
  {
    box-shadow: 0 -4px 0 .6 #faeac6 inset;
  }

  .forum-table-header, body .forum-table-header th, body .forum-table-footer, #ctl00_cphRoblox_Message1_ctl00_CenterColumn > table > tbody > tr:nth-child(1) > th, #ctl00_cphRoblox_CenterColumn > table > tbody > tr:nth-child(1) > th
  {
    background: #faeac6 !important;
  }

  .rbx-upgrade-now #upgrade-now-button, .rbx-btn-secondary-xs.btn-more, #AjaxCommentsContainer > div > div.comment-form > form > button, .rbx-vip-server-create, .btn-secondary-xs
  {
    background-color: #faeac6 !important;
    border-color: #faeac6;
  }

  .rbx-upgrade-now #upgrade-now-button:hover, .rbx-btn-secondary-xs.btn-more:hover, #AjaxCommentsContainer > div > div.comment-form > form > button:hover, .rbx-vip-server-create:hover, .btn-secondary-xs:hover
  {
    background: #faeac6 !important;
    border-color: #faeac6;
  }

  #TopAbpContainer, .ad-annotations, #LeftGutterAdContainer, #RightGutterAdContainer, #Skyscraper-Adp-Right, #Skyscraper-Adp-Left,
.abp-spacer, #GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even, #GamesListContainer1 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd, #GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-even, #GamesListContainer8 > div.games-list > ul > div.abp.in-game-search-ad.dynamic-ad.ad-order-odd, .sponsored-game, .alert-info, #mCSB_1_container > ul > li.font-bold.small, #mCSB_1_container > ul > li.rbx-nav-sponsor
  {
    display: none !important;
  }

  #navbar-search-input, #navbar-search-btn
  {
    border: 1px solid #faeac6;
  }

  body
  {
    background: transparent !important;
  }

  .content
  {
    background: transparent !important;
  }

  .container-footer
  {
    position: static;
  }

  html
  {
    width: 100% !important;
    height: 100% !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-image: url("data:image/jpeg;base64,") !important;
  }
  
#party_none_title, div.friend_dock_chatbox_titlebar.chat-header-blink-off
  {
    background: linear-gradient(to bottom, #faeac6, #faeac6);
  }

  #ctl00_cphRoblox_RightColumn, #Body > table > tbody > tr > td:nth-child(3), #Body > table > tbody > tr > td:nth-child(4)
  {
    display: none;
  }

  #GamesPageLeftColumn
  {
    width: auto;
    margin-right: 10px !important;
    margin-left: 10px !important;
  }

  #GamesListsContainer > div
  {
    background-color: transparent !important;
    width: 100% !important;
  }
  
  #navigation
  {
    background-color: #f8efc6;
  }

  .rbx-btn-primary-lg
  {
    background-color: #f8efc6;
  }

  .rbx-btn-primary-lg:hover, .rbx-btn-primary-lg:focus
  {
    background-color: #f8efc6;
  }
/*Style by @Keixsra/sarohaplays*/
  .avatar-back
  {
    background-image: url(https://i.ibb.co/dwGWypC2/ead0db186e3906c56af844a20d80d5d3.jpg);
  }
/* ---------- footer ---------- */

.container-footer,
.footer,
.footer-container {
    background: transparent !important;
    box-shadow: none !important;
  }
/* ---------- profile page ---------- */
/* Profile header/avatar area */
.profile-header,
.profile-header-container,
.profile-avatar-container,
.profile-avatar-right,
.profile-info,
.profile-header-content,
.profile-banner,
.profile-cover {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
    border-color: transparent !important;
}
/* profile avatar box */
.profile-avatar-left,
.profile-avatar-right,
.profile-avatar,
.profile-avatar-container,
.avatar-card,
.avatar-card-container {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
}
 /* SIDEBAR */
#left-navigation-container,
#left-navigation-container .left-nav,
#left-navigation-container .left-nav > div,
#left-navigation-container .left-nav nav,
#left-navigation-container .left-nav nav > ul {
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
}
#left-navigation-container {
    background: transparent !important;
}
#left-navigation-container .left-nav a,
#left-navigation-container .left-nav li {
    background-color: transparent !important;
}
/* selected sidebar item */
#left-navigation-container .left-nav li[data-testid="selected"],
#left-navigation-container .left-nav li[aria-current="page"],
#left-navigation-container .left-nav a[aria-current="page"] {
    background: rgba(255, 232, 238, 0.75) !important;
}
/* hover */
#left-navigation-container .left-nav li:hover {
    background: rgba(255, 232, 238, 0.55) !important;
}
/* search */
#navbar-search-input,
#navbar-search-btn {
    background-color: #fffeed !important;
    border: 1px solid #fffeed !important;
    box-shadow: none !important;
}
/* + add friends */
.add-friends-icon {
    color: #f2b4b9 !important;
    fill: #f2b4b9 !important;
    stroke: #f2b4b9 !important;
}
/* main page scrollbar */
html::-webkit-scrollbar {
    width: 8px !important;
}

html::-webkit-scrollbar-track {
    background: #fcf0d9 !important;
}

html::-webkit-scrollbar-thumb {
    background: #f7cdbd !important;
    border-radius: 10px !important;
    border: 2px solid #fcf0d9 !important;
}

html::-webkit-scrollbar-thumb:hover {
    background: #f7cdbd !important;
}
/* sidebar scrollbar */

.scroll-y {
    scrollbar-width: thin !important;
    scrollbar-color: #f7cdbd #fceccf !important;
}
.scroll-y::-webkit-scrollbar {
    width: 8px !important;
}
.scroll-y::-webkit-scrollbar-track {
    background: #fceccf !important;
    border-radius: 10px !important;
}
.scroll-y::-webkit-scrollbar-thumb {
    background: #f7cdbd !important;
    border-radius: 10px !important;
    border: 2px solid #fceccf !important;
}
.scroll-y::-webkit-scrollbar-thumb:hover {
    background: #f8efc6 !important;
}
/* accept/ignore */ 
.avatar-card-btns {
    background: #f8efc6 !important;
    background-color: transparent !important;
    border: transparent !important;
    box-shadow: none !important;
    border-radius: 8px !important;
    padding: 6px !important;
}
.avatar-card-btns .ignore-friend,
.avatar-card-btns .accept-friend {
    background: revert !important;
    background-color: revert !important;
    color: revert !important;
    border-color: revert !important;
    box-shadow: revert !important;
}
.avatar-card-btns .ignore-friend *,
.avatar-card-btns .accept-friend * {
    color: inherit !important;
}
/* friends/following/followers/request */
#friends .rbx-tab-heading,
#following .rbx-tab-heading,
#followers .rbx-tab-heading,
#requests .rbx-tab-heading {
    background-color: #fbe9c5 !important;
}
/* No results found */
.section-content-off {
    background-color: transparent !important;
}
/* unfollow */
ul.dropdown-menu {
    background-color: #f8efc6 !important;
}
ul.dropdown-menu li {
    background-color: #f8efc6 !important;
}
ul.dropdown-menu li a.friend-unfollow {
    background-color: #f8efc6 !important;
}
/* avatar tabs bar */
.rbx-tabs-horizontal.avatar-tabs-scroller {
    background: transparent !important;
}
.rbx-tabs-horizontal.avatar-tabs-scroller > ul,
.rbx-tabs-horizontal.avatar-tabs-scroller > ul > li,
.rbx-tabs-horizontal.avatar-tabs-scroller .rbx-tab-heading,
.rbx-tabs-horizontal.avatar-tabs-scroller .scroller-new {
    background: transparent !important;
}
/* avatar dropdown panels */
.avatar-tabs-scroller ~ *,
.avatar-tabs-scroller .dropdown-menu,
.avatar-tabs-scroller + .dropdown-menu {
    background-color: #f7cdbd !important;
}
.avatar-dropdown,
.avatar-tabs-dropdown,
.rbx-dropdown-menu,
.dropdown-menu {
    background-color: #f7cdbd !important;
}
.avatar-dropdown li,
.avatar-tabs-dropdown li,
.rbx-dropdown-menu li,
.dropdown-menu li {
    background-color: #f7cdbd !important;
}
/* avatar scaling panel */
.scaling-tab {
    background-color:  transparent !important;
}
.scaling-tab .section-content {
    background-color:  transparent !important;
}
.scaling-tab .scaling-info,
.scaling-tab .avatar-type-container,
.scaling-tab .avatar-type-contents-container,
.scaling-tab .section-sliders,
.scaling-tab .scale-container {
    background-color:  transparent !important;
}
  /* inventory vertical menu */
#vertical-menu {
    background-color: transparent !important;
}
#vertical-menu .menu-option {
    background-color: transparent !important;
}
#vertical-menu .menu-option-content {
    background-color: transparent !important;
}
/* reco */ 
.recommendations-container {
    background: transparent !important;
}
/* group */
.groups-list-sidebar,
.groups-list-new,
.groups-list-items-container,
.groups-list-item {
    background: transparent !important;
}
/* announcements */
.group-announcements-display .announcement-display {
    background: #f7cdbd !important;
    border-radius: 10px !important;
    padding: 20px !important;
}
/* text */
.group-announcements-display .announcement-display-title,
.group-announcements-display .announcement-display-body,
.group-announcements-display .group-forums-user-display,
.group-announcements-display .user-display-meta,
.group-announcements-display .groups-content-reactions-count {
    color: #393B3D !important;
}
/* owner badge */
.group-announcements-display .foundation-web-badge {
    background: #f7cdbd !important;
}
/* three dots button */
.group-announcements-display .announcement-display-context-menu button {
    background: transparent !important;
}
/* emojis unchanged */
.group-announcements-display .reaction-emote {
    color: initial !important;
}
/* message */
.private-message-row {
    background-color: #f7cdbd !important;
}
.text-caption-medium:nth-child(1) {
	  background-color: #f7cdbd !important;
}
.bg-surface-300:nth-child(2) {
	  background-color: #f7cdbd !important;
}
/* notif */
.notification-stream-header {
    background-color: #f8efc6 !important;
}
/* notif ct */
.notification-stream-body {
    background-color: #f7cdbd !important;
}
.notification-stream-list {
    background-color: #f7cdbd !important;
}
.sendr-notification-background {
    background-color: #f7cdbd !important;
}
.legacy-notif-base {
    background-color: #f7cdbd !important;
}
/* bt/ropro*/ 
/* exp */
#games-switcher,
#games-switcher .btr-games-list,
#games-switcher .btr-game,
#games-switcher .btr-game-content {
    background: transparent !important;
}
  .btr-game-button {
    background: transparent !important;
    background-color: transparent !important;
}
/* favorites */
.btr-profile-favorites .section-content {
    background: transparent !important;
}
/* bio */
.btr-profile-about > .section-content {
    background: transparent !important;
}
/* badge */
.btr-profile-robloxbadges > .section-content {
	background: transparent !important;
}
.btr-profile-playerbadges > .section-content {
	background: transparent !important;
}
/* groups */
.btr-profile-groups .section-content {
    background: transparent !important;
}
/* marketplace header */
.catalog-header,
.catalog-heading-container,
.catalog-heading-actions,
.search-bars,
.search-container,
.search-container-original,
#search-bar,
#search-bar-container {
    background: transparent !important;
    background-color: #f8efc6 !important;;
    box-shadow: transparent !important;
}
.catalog-header .heading-container {
    background: transparent !important;
}
/* search input */
.catalog-header input.search-input {
    background: #f7cdbd !important;
}
.catalog-heading-container,
.catalog-heading-actions,
.catalog-search-options-top-bar,
.catalog-search-options-top-bar > div,
.catalog-heading-container .topic-container {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important;
}
/* filter buttons */
.catalog-heading-container .filter-select {
    background: transparent !important;
    box-shadow: none !important;
}
/* topic buttons */
.catalog-heading-container .topic {
    background: #f7cdbd !important;
    box-shadow: #f7cdbd !important;
}
/*Style by @Keixsra/sarohaplays*/
}
